LOCK TABLES `reviews` WRITE;
/*!40000 ALTER TABLE `reviews` DISABLE KEYS */;
INSERT INTO `reviews` VALUES (1,17,NULL,'Vũ Minh Trí','0975***166',5,'Đánh giá sản phẩm chính hãng','Hàng chuẩn Panasonic 100%, có tem cào chống hàng giả và quét mã QR xác thực chính hãng. Đã lắp cho công trình, công tắc bấm rất êm tay và đanh chắc.',NULL,NULL,1,2,1,'2026-08-26 21:23:54'),(2,17,NULL,'Vũ Minh Trí','0975***166',5,'Đánh giá sản phẩm chính hãng','Đã kiểm tra hồ sơ CO/CQ và hóa đơn VAT xuất đầy đủ, phục vụ nghiệm thu dự án rất thuận lợi. Đóng gói cẩn thận, giao hỏa tốc chân công trình trong 2 tiếng.',NULL,NULL,1,14,1,'2026-08-05 13:23:54'),(3,17,NULL,'Hoàng Kim Ngân','0915***330',5,'Đánh giá sản phẩm chính hãng','Chất liệu nhựa Urea Resin chống cháy cao cấp, tiếp điểm đồng dầy dặn dập hồ quang cực tốt. An tâm tuyệt đối khi sử dụng tải lớn.',NULL,NULL,1,25,1,'2026-07-01 07:23:54'),(4,17,NULL,'Ngô Tấn Tài','0963***224',5,'Đánh giá sản phẩm chính hãng','Giá chiết khấu dự án tốt hơn nhiều so với thị trường, nhân viên tư vấn kỹ thuật hỗ trợ tính toán tải rất nhiệt tình. Sẽ tiếp tục đồng hành ở các dự án tiếp theo.',NULL,NULL,1,4,1,'2026-06-25 22:23:54'),(5,17,NULL,'Hoàng Kim Ngân','0915***330',4,'Đánh giá sản phẩm chính hãng','Thiết bị hoạt động ổn định, phích cắm vào rất khít và an toàn. Rất đáng đồng tiền, đánh giá 5 sao cho chất lượng dịch vụ.',NULL,NULL,1,9,1,'2026-08-28 20:23:54'),(6,17,NULL,'Lê Hoàng Long','0904***882',5,'Đánh giá sản phẩm chính hãng','Đã kiểm tra hồ sơ CO/CQ và hóa đơn VAT xuất đầy đủ, phục vụ nghiệm thu dự án rất thuận lợi. Đóng gói cẩn thận, giao hỏa tốc chân công trình trong 2 tiếng.',NULL,NULL,1,19,1,'2026-07-11 05:23:54'),(7,17,NULL,'Lê Hoàng Long','0904***882',5,'Đánh giá sản phẩm chính hãng','Thiết kế phẳng tràn viền cực kỳ sang trọng, lắp lên tường thạch cao rất phẳng và sắc nét. Gia chủ rất ưng ý.',NULL,NULL,1,4,1,'2026-07-02 10:23:54'),(8,18,NULL,'Bùi Quang Khải','0902***779',5,'Đánh giá sản phẩm chính hãng','Đã mua nhiều lần của tổng kho, hàng luôn có sẵn số lượng lớn kể cả mã hiếm. Bảo hành 24 tháng chính hãng đổi mới nhanh gọn.',NULL,NULL,1,14,1,'2026-06-21 23:23:54'),(9,18,NULL,'Đỗ Quốc Bảo','0988***415',5,'Đánh giá sản phẩm chính hãng','Thiết kế phẳng tràn viền cực kỳ sang trọng, lắp lên tường thạch cao rất phẳng và sắc nét. Gia chủ rất ưng ý.',NULL,NULL,1,12,1,'2026-09-09 08:23:54'),(10,18,NULL,'Ngô Tấn Tài','0963***224',4,'Đánh giá sản phẩm chính hãng','Thiết bị hoạt động ổn định, phích cắm vào rất khít và an toàn. Rất đáng đồng tiền, đánh giá 5 sao cho chất lượng dịch vụ.',NULL,NULL,1,21,1,'2026-09-11 03:23:54'),(11,18,NULL,'Đinh Mạnh Hùng','0971***608',5,'Đánh giá sản phẩm chính hãng','Đã kiểm tra hồ sơ CO/CQ và hóa đơn VAT xuất đầy đủ, phục vụ nghiệm thu dự án rất thuận lợi. Đóng gói cẩn thận, giao hỏa tốc chân công trình trong 2 tiếng.',NULL,NULL,1,26,1,'2026-08-18 01:23:54'),(12,19,NULL,'Phạm Đức Thắng','0936***993',4,'Đánh giá sản phẩm chính hãng','Thiết bị hoạt động ổn định, phích cắm vào rất khít và an toàn. Rất đáng đồng tiền, đánh giá 5 sao cho chất lượng dịch vụ.',NULL,NULL,1,4,1,'2026-07-24 14:23:54'),(13,19,NULL,'Lê Hoàng Long','0904***882',5,'Đánh giá sản phẩm chính hãng','Đã mua nhiều lần của tổng kho, hàng luôn có sẵn số lượng lớn kể cả mã hiếm. Bảo hành 24 tháng chính hãng đổi mới nhanh gọn.',NULL,NULL,1,11,1,'2026-08-02 09:23:54'),(14,19,NULL,'Phạm Đức Thắng','0936***993',5,'Đánh giá sản phẩm chính hãng','Chất liệu nhựa Urea Resin chống cháy cao cấp, tiếp điểm đồng dầy dặn dập hồ quang cực tốt. An tâm tuyệt đối khi sử dụng tải lớn.',NULL,NULL,1,17,1,'2026-09-19 04:23:54'),(15,20,NULL,'Lê Hoàng Long','0904***882',5,'Đánh giá sản phẩm chính hãng','Hàng chuẩn Panasonic 100%, có tem cào chống hàng giả và quét mã QR xác thực chính hãng. Đã lắp cho công trình, công tắc bấm rất êm tay và đanh chắc.',NULL,NULL,1,25,1,'2026-10-13 04:23:54'),(16,20,NULL,'Hoàng Kim Ngân','0915***330',4,'Đánh giá sản phẩm chính hãng','Lắp đặt cắm nhanh rất tiện lợi, tiết kiệm 50% thời gian đấu nối dây cho thợ. Sản phẩm rất tốt.',NULL,NULL,1,13,1,'2026-07-09 11:23:54'),(17,20,NULL,'Hoàng Kim Ngân','0915***330',5,'Đánh giá sản phẩm chính hãng','Hàng chuẩn Panasonic 100%, có tem cào chống hàng giả và quét mã QR xác thực chính hãng. Đã lắp cho công trình, công tắc bấm rất êm tay và đanh chắc.',NULL,NULL,1,8,1,'2026-09-13 13:23:54'),(18,20,NULL,'Bùi Quang Khải','0902***779',5,'Đánh giá sản phẩm chính hãng','Aptomat đóng cắt rất nhạy, lực gạt chắc chắn, đúng chuẩn Nhật Bản JIS. Hàng mới nguyên hộp 100%.',NULL,NULL,1,12,1,'2026-10-07 01:23:54'),(19,20,NULL,'Phạm Đức Thắng','0936***993',4,'Đánh giá sản phẩm chính hãng','Thiết bị hoạt động ổn định, phích cắm vào rất khít và an toàn. Rất đáng đồng tiền, đánh giá 5 sao cho chất lượng dịch vụ.',NULL,NULL,1,8,1,'2026-09-29 12:23:54'),(20,20,NULL,'Đỗ Quốc Bảo','0988***415',5,'Đánh giá sản phẩm chính hãng','Aptomat đóng cắt rất nhạy, lực gạt chắc chắn, đúng chuẩn Nhật Bản JIS. Hàng mới nguyên hộp 100%.',NULL,NULL,1,20,1,'2026-08-20 07:23:54'),(21,20,NULL,'Lê Hoàng Long','0904***882',5,'Đánh giá sản phẩm chính hãng','Đèn ánh sáng rất dịu mắt, chỉ số hoàn màu CRI cao, không hề có hiện tượng chớp nháy (Flicker-Free). Rất phù hợp phòng ngủ và phòng khách.',NULL,NULL,1,9,1,'2026-08-30 23:23:54'),(22,20,NULL,'Bùi Quang Khải','0902***779',5,'Đánh giá sản phẩm chính hãng','Giá chiết khấu dự án tốt hơn nhiều so với thị trường, nhân viên tư vấn kỹ thuật hỗ trợ tính toán tải rất nhiệt tình. Sẽ tiếp tục đồng hành ở các dự án tiếp theo.',NULL,NULL,1,25,1,'2026-07-12 19:23:54'),(23,21,NULL,'Trần Anh Tuấn','0983***721',5,'Đánh giá sản phẩm chính hãng','Thiết kế phẳng tràn viền cực kỳ sang trọng, lắp lên tường thạch cao rất phẳng và sắc nét. Gia chủ rất ưng ý.',NULL,NULL,1,9,1,'2026-07-19 20:23:54'),(24,21,NULL,'Vũ Minh Trí','0975***166',5,'Đánh giá sản phẩm chính hãng','Đã kiểm tra hồ sơ CO/CQ và hóa đơn VAT xuất đầy đủ, phục vụ nghiệm thu dự án rất thuận lợi. Đóng gói cẩn thận, giao hỏa tốc chân công trình trong 2 tiếng.',NULL,NULL,1,4,1,'2026-09-14 07:23:54'),(25,21,NULL,'Trần Anh Tuấn','0983***721',5,'Đánh giá sản phẩm chính hã